bool nt(int n) {
    for (int i = 2; i <= sqrt(n); i++)
        if (n % i == 0) return false;
    return n > 1;
}

int dem(int a[][205], int n, int m) {
    int ans = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (nt(a[i][j])) ++ans;
    return ans;
}
